@Test
void completedWorkspaceToolProjectsStructuredDiffWithoutChangingCore() throws Exception {
    var provider = new ScriptedModelProvider()
            .enqueue(List.of(new ScriptedModelProvider.Step.Tool("call-1", "write", Map.of("path", "a.txt")),
                    new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)))
            .enqueue(List.of(new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
    var store = new MemoryHostStore();
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
            .tool(ToolDefinition.sync("write", "write", Map.of("type", "object"),
                    (arguments, cancellation) -> ToolDefinition.ToolResult.text("written")).alwaysAllow()).build();
         var sessions = new SessionApplicationService(runtime);
         var harness = new Harness(sessions, new PromptApplicationService(sessions, store))) {
        harness.request(1, "initialize", Map.of("protocolVersion", 2, "clientCapabilities", Map.of()));
        harness.request(2, "auth/login", Map.of("methodId", "local"));
        String sessionId = harness.request(3, "session/new", Map.of("cwd", "."))
                .path("result").path("sessionId").asText();
        List<JsonNode> values = harness.requestCollecting(4, "session/prompt", Map.of("sessionId", sessionId,
                "prompt", List.of(Map.of("type", "text", "text", "write"))));
        values.addAll(harness.updatesUntilIdle());
        assertTrue(values.stream().anyMatch(message -> "diff".equals(message.path("params").path("update")
                .path("content").path(0).path("type").asText())));
    }
}

